// draws the vertical scrollbar INSIDE the `padding: 0 1` box — row strip, then the
// bar, then the right padding cell, then the border (`…▅▅ ▎`, verified against a
// Textual capture) — so the bar starts 1 (border) + 1 (padding) cells before the
// right edge. Only meaningful while scrolling.
func (m Model) barLeft() int { return m.totalWidth() - 2 - scrollbar.VThickness }

// scrollbarRegion reports whether local (x,y) is over the scrollbar gutter.
func (m Model) scrollbarRegion(localX, localY int) bool {
	if !m.scrolls() {
		return false
	}
	return localX >= m.barLeft() && localX < m.barLeft()+scrollbar.VThickness &&
		localY >= 1 && localY < 1+m.visibleN()
}

// beginGrab handles a left press on the scrollbar at local-Y y, as Textual's
// ScrollBar does: on the thumb it grabs for a relative drag; on the track above /
// below it the list pages one window (scroll_page_up / scroll_page_down: ± the
// visible height, clamped) and does NOT grab, so a held track press neither
// repeats nor drags (Textual oracle, widget/internal/trackpress). Track Y excludes
// the top border row.
func (m *Model) beginGrab(y int) {
	trackY := y - 1
	start, end := scrollbar.ThumbExtent(m.visibleN(), len(m.items), m.offset)
	switch {
	case start > end: // no thumb drawn: Textual's bar carries no actions
		return
	case trackY < start:
		m.offset -= m.visibleN()
	case trackY > end:
		m.offset += m.visibleN()
	default:
		m.sbGrabbed = true
		m.grabAnchor, m.grabBase = trackY, m.offset
		return
	}
	m.clampOffset()
}

// dragTo updates the offset from a drag to local-Y y, scaled by content/window.
func (m *Model) dragTo(y int) {
	size := m.visibleN()
	if size <= 0 {
		return
	}
	trackY := y - 1
	delta := float64(trackY-m.grabAnchor) * float64(len(m.items)) / float64(size)
	m.offset = m.grabBase + int(math.Round(delta))
	m.clampOffset()
}

// ScrollbarAt reports whether local (x,y) is over the right-edge scrollbar gutter.
func (m Model) ScrollbarAt(localX, localY int) bool { return m.scrollbarRegion(localX, localY) }

// SetScrollbarHovered sets whether the pointer is over the scrollbar gutter.
func (m *Model) SetScrollbarHovered(b bool) { m.sbHovered = b }

// Grabbing reports whether the scrollbar thumb is currently grabbed.
func (m Model) Grabbing() bool { return m.sbGrabbed }

// GrabScrollbar handles a scrollbar press at local-Y y: it grabs the thumb, or
// pages one window from a track press (which leaves [Model.Grabbing] false).
func (m *Model) GrabScrollbar(localY int) {
	if m.scrolls() {
		m.beginGrab(localY)
	}
}

// DragScrollbar drags a grabbed thumb to local-Y y, scrolling the window.
func (m *Model) DragScrollbar(localY int) {
	if m.sbGrabbed {
		m.dragTo(localY)
	}
}

// ReleaseScrollbar releases a grabbed thumb.
func (m *Model) ReleaseScrollbar() { m.sbGrabbed = false }

// Wheel scrolls the window one notch up or down; it never moves the highlight.
// A no-op when the list does not overflow.
func (m *Model) Wheel(up bool) {
	if !m.scrolls() {
		return
	}
	if up {
		m.offset -= wheelStep
	} else {
		m.offset += wheelStep
	}
	m.clampOffset()
}

// thumbColor resolves the scrollbar thumb colour from its interaction state:
// resting $scrollbar, hovered $scrollbar-hover, grabbed $scrollbar-active.
func (m Model) thumbColor() gocolor.Color {
	tok := style.Scrollbar
	if m.sbGrabbed {
		tok = style.ScrollbarActive
	} else if m.sbHovered {
		tok = style.ScrollbarHover
	}
	return style.Active().Color(tok)
}

// --- rendering --------------------------------------------------------------

// baseBg is the row/interior background for non-special cells: Textual's
// `background-tint: $foreground 5%` ($surface-focused-tint) lightens the whole
// interior while the list is focused, plain $surface otherwise. Implemented (not
// accepted) per the focus-tint preference — the focused interior then matches
// Textual; the highlighted/hovered rows draw their own opaque bg on top.
func (m Model) baseBg() gocolor.Color {
	if m.focused {
		return style.Active().Color(style.SurfaceFocusedTint)
	}
	return style.Active().Color(style.Surface)
}

// rowColors returns the label fg/bg/bold for row i. A disabled row is $text-disabled
// on the interior background (never highlights/hovers). Otherwise the highlighted
// row is the block cursor (bright focused, with Textual's `auto` cursor text
// resolved as $block-cursor-foreground / muted blurred); a hovered non-highlighted
// row gets the hover tint; else plain $text on the interior background. (Same
// mapping as widget/optionlist.)
func (m Model) rowColors(i int) (fg, bg gocolor.Color, bold bool) {
	switch {
	case m.items[i].Disabled:
		return style.Active().Color(style.TextDisabled), m.baseBg(), false
	case i == m.highlight && m.focused:
		return style.Active().Color(style.BlockCursorForeground), style.Active().Color(style.Primary), true
	case i == m.highlight:
		return style.Active().Color(style.Text), style.Active().Color(style.BlockCursorBlurredBackground), false
	case i == m.hovered:
		return style.Active().Color(style.Text), style.Active().Color(style.BlockHoverBackground), false
	default:
		return style.Active().Color(style.Text), m.baseBg(), false
	}
}

// gutter builds the ▐X▌ toggle for a row: $panel side caps painted on the row
// background rowBg (so they blend into the highlight on the cursor row, matching
// Textual's side_style), the inner X painted on $panel — $text-success (green)
// when this row is checked, else $panel-darken-2. A trailing space on rowBg
// completes the 4-cell gutter.
func (m Model) gutter(checked bool, rowBg gocolor.Color) string {
	panel := style.Active().Color(style.Panel)
	innerFg := style.Active().Color(style.PanelDarken2)
	if checked {
		innerFg = style.Active().Color(style.TextSuccess)
	}
	side := lipgloss.NewStyle().Foreground(panel).Background(rowBg)
	inner := lipgloss.NewStyle().Foreground(innerFg).Background(panel)
	space := lipgloss.NewStyle().Background(rowBg).Render(" ")
	return side.Render(buttonLeft) + inner.Render(buttonInner) + side.Render(buttonRight) + space
}

// borderToken is the focused $border when focused, else $border-blurred.
func (m Model) borderToken() style.Token {
	if m.focused {
		return style.Border
	}
	return style.BorderBlurred
}

// Render returns the tall-bordered $surface checkbox column (padding 0 1). Each row
// is the ▐X▌ gutter + the label, padded to the content width so the row background
// spans the row. When the list overflows its height cap, only the visible window
// is drawn and the vertical scrollbar takes VThickness columns between the row
// strip and the right padding cell (Textual's layout; the outer width stays
// constant). Every item is exactly ONE physical line — outerHeight and RowAt rely
// on it — so a label wider than the room left beside the gutter ends in Textual's
// `text-overflow: ellipsis` "…" ([rowtext.Ellipsis]) and a strip narrower than the
// gutter clips it; it never wraps, and a label with line breaks shows only its
// first line, tabs expanded ([Model.rowText]).
func (m Model) Render() string {
	optW := m.contentWidth() // the option strip (gutter + label), inside the padding
	var bar string
	if m.scrolls() {
		optW -= scrollbar.VThickness // >= 0: contentWidth reserves the bar
		bar = scrollbar.RenderVertical(m.height, len(m.items), m.offset,
			m.thumbColor(), style.Active().Color(style.ScrollbarBackground))
	}
	n := m.visibleN()
	pad := lipgloss.NewStyle().Background(m.baseBg())
	rows := make([]string, n)
	for r := 0; r < n; r++ {
		i := m.offset + r
		fg, bg, bold := m.rowColors(i)
		g := m.gutter(m.selected[m.items[i].Value], bg)
		// The label room is what the strip (already narrowed by the bar) leaves
		// beside the gutter. A negative room means the strip clips the gutter
		// itself — Textual's screen crop — which the Truncate below does.
		text := m.rowText(i)
		if room := optW - gutterWidth; room >= 0 {
			text = rowtext.Ellipsis(text, room)
		}
		label := lipgloss.NewStyle().Foreground(fg).Background(bg).
			Bold(bold || m.items[i].Bold).Render(text)
		// The option strip (gutter + label, filled to optW) carries the row's own
		// background — so the block-cursor / hover highlight covers exactly the
		// option line, as in Textual. Lip Gloss's Width word-wraps BEFORE MaxWidth
		// truncates each line, so the content is clipped (ANSI-aware) to optW first;
		// Width then only pads. A zero-cell strip (the bar ate the whole content
		// width) renders nothing: Lip Gloss reads Width(0)/MaxWidth(0) as
		// unrestricted, which would overflow the row past the barLeft/RowAt geometry.
		strip := ""
		if optW > 0 {
			strip = lipgloss.NewStyle().Background(bg).Width(optW).MaxWidth(optW).
				Render(ansi.Truncate(g+label, optW, ""))
		}
		// The one-cell horizontal padding (Textual `padding: 0 1`) is part of the
		// CONTAINER, so it takes the interior background (the focus tint / $surface),
		// NOT the row highlight — matching Textual, whose highlight stops at the
		// option strip and leaves the padding tinted.
		if bar != "" {
			rows[r] = pad.PaddingLeft(1).Render(strip) // right padding follows the bar
		} else {
			rows[r] = pad.Padding(0, 1).Render(strip)
		}
	}
	body := lipgloss.JoinVertical(lipgloss.Left, rows...)
	if bar != "" {
		right := pad.Width(1).Height(n).Render("")
		body = lipgloss.JoinHorizontal(lipgloss.Top, body, bar, right)
	}
	// The border background follows the interior — the focused 5% tint extends into
	// the frame (Textual tints the whole container).
	s := style.TallBorder(lipgloss.NewStyle().Background(m.baseBg()), m.borderToken())
	return s.Render(body)
}

// View implements tea.Model (Bubble Tea v2). MouseModeAllMotion is requested so the
// host receives clicks AND bare hover motion (the row tint).
func (m Model) View() tea.View {
	v := tea.NewView(m.Render())
	v.MouseMode = tea.MouseModeAllMotion
	return v
}
